DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT103-S3-Q5$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT103-S3-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S3-Q5$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$the company will issue another upgrade that corrects the problems with the current upgrade$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S3-Q5 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S3-Q5$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$some of the problems people have experienced with the upgrade have been quite serious$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S3-Q5 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S3-Q5$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$a significant number of people have experienced problems with the upgrade but have not reported them$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S3-Q5 C'; END IF; END $guard$;
