DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S3-Q5$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$some of the reported problems were a result of users failing to follow instructions$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S3-Q5 E'; END IF; END $guard$;
