INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT103-S3-Q5$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$The consumer is very unlikely to have a problem with the upgrade.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Nearly 3,000 copies were distributed, and fewer than 100 problem calls reached the company.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$The company has counted calls, not problems. What if many customers experienced a problem but did not call? Fewer than 100 reports out of nearly 3,000 copies would not then tell us the actual failure rate. This is a reporting sample with missing cases.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the possibility that problems went unreported.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT103-S3-Q5$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$A later corrective upgrade could help later users. It does not show how many problems the current upgrade causes now.$batch01$), ($batch01$B$batch01$, $batch01$Severe problems would matter to the consumer, but the argument estimates *likelihood*. Seriousness does not show that more people have problems than the number of calls suggests.$batch01$), ($batch01$C$batch01$, $batch01$If many people had problems without calling, reported calls undercount actual failures. The company's inference from “few calls” to “few problems” then collapses. The reusable question is whether the method of counting captures the event the conclusion is about.$batch01$), ($batch01$D$batch01$, $batch01$Problems without the upgrade do not tell us whether this upgrade causes problems for its users.$batch01$), ($batch01$E$batch01$, $batch01$If some reported problems came from users' mistakes, even fewer reports would count as defects caused by the upgrade. That does not expose the company's undercount.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT103-S3-Q5$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
